  4→.sd-header {
  5→  display: flex;
  6→  align-items: center;
  7→  justify-content: space-between;
  8→  padding: 12px 16px;
  9→  font-size: 14px;
 10→  font-weight: 700;
 11→  letter-spacing: 0.5px;
 12→  color: #4a9eff;
 13→  border-bottom: 1px solid #3a3a3a;
 14→  flex-shrink: 0;
 15→}
 16→
 17→.sd-header__title {
 18→  flex: 1;
 19→}
 20→
 21→.sd-header__status {
 22→  font-size: 11px;
 23→  font-weight: 400;
 24→  color: #666;
 25→}
 26→
 27→.sd-header__status--connecting {
 28→  color: #e6a817;
 29→}
 30→
 31→.sd-header__status--disconnected {
 32→  color: #e65050;
 33→}
 34→
 35→/* ── Stage indicator ─────────────────────────────────────────────── */
 36→
 37→.sd-stage-bar {
 38→  display: flex;
 39→  align-items: center;
 40→  gap: 8px;
 41→  padding: 6px 16px;
 42→  background: #1a2a3a;
 43→  border-bottom: 1px solid #3a3a3a;
 44→  flex-shrink: 0;
 45→  font-size: 12px;
 46→  animation: sd-pulse 1.5s ease-in-out infinite;
 47→}
 48→
 49→.sd-stage__label {
 50→  color: #4a9eff;
 51→  font-weight: 700;
 52→  letter-spacing: 0.5px;
 53→}
 54→
 55→.sd-stage__detail {
 56→  color: #888;
 57→}
 58→
 59→@keyframes sd-pulse {
 60→  0%, 100% { opacity: 1; }
 61→  50% { opacity: 0.6; }
 62→}
 63→
 64→.sd-messages {
 65→  flex: 1;
 66→  overflow-y: auto;
 67→  padding: 12px;
 68→  display: flex;
 69→  flex-direction: column;
 70→  gap: 8px;
 71→}
 72→
 73→/* ── Messages ─────────────────────────────────────────────────────── */
 74→
 75→.sd-message {
 76→  display: flex;
 77→  flex-direction: column;
 78→  gap: 2px;
 79→  padding: 8px 10px;
 80→  border-radius: 6px;
 81→  font-size: 13px;
 82→  line-height: 1.45;
 83→  word-wrap: break-word;
 84→}
 85→
 86→.sd-message--user {
 87→  background: #2a3a4a;
 88→  align-self: flex-end;
 89→  max-width: 90%;
 90→}
 91→
 92→.sd-message--agent {
 93→  background: #333;
 94→  align-self: flex-start;
 95→  max-width: 90%;
 96→}
 97→
 98→.sd-message--system {
 99→  background: transparent;
100→  color: #888;
101→  font-style: italic;
102→  font-size: 12px;
103→  align-self: center;
104→}
105→
106→.sd-message__label {
107→  font-size: 11px;
108→  font-weight: 600;
109→  color: #888;
110→  text-transform: uppercase;
111→  letter-spacing: 0.3px;
112→}
113→
114→.sd-message--user .sd-message__label {
115→  color: #4a9eff;
116→}
117→
118→.sd-message--agent .sd-message__label {
119→  color: #6fcf97;
120→}
121→
122→.sd-message__body {
123→  color: #eee;
124→}
125→
126→.sd-message--system .sd-message__body {
127→  color: #888;
128→}
