130→/* ── Input bar ────────────────────────────────────────────────────── */
131→
132→.sd-input-bar {
133→  display: flex;
134→  gap: 6px;
135→  padding: 10px 12px;
136→  border-top: 1px solid #3a3a3a;
137→  flex-shrink: 0;
138→}
139→
140→.sd-input {
141→  flex: 1;
142→  background: #1e1e1e;
143→  border: 1px solid #444;
144→  border-radius: 6px;
145→  padding: 8px 10px;
146→  color: #eee;
147→  font-size: 13px;
148→  outline: none;
149→  transition: border-color 0.15s;
