151→
152→.sd-input:focus {
153→  border-color: #4a9eff;
154→}
155→
156→.sd-input::placeholder {
157→  color: #666;
158→}
159→
160→.sd-send-btn {
161→  background: #4a9eff;
162→  color: #fff;
163→  border: none;
164→  border-radius: 6px;
165→  padding: 8px 14px;
166→  font-size: 13px;
167→  font-weight: 600;
168→  cursor: pointer;
