170→  flex-shrink: 0;
171→}
172→
173→.sd-send-btn:hover {
174→  background: #3a8eef;
175→}
176→
177→.sd-send-btn:active {
178→  background: #2a7edf;
179→}
180→
181→.sd-send-btn:disabled {
182→  background: #555;
183→  cursor: not-allowed;
184→}
