186→/* ── Scrollbar ────────────────────────────────────────────────────── */
187→
188→.sd-messages::-webkit-scrollbar {
189→  width: 6px;
190→}
191→
192→.sd-messages::-webkit-scrollbar-track {
193→  background: transparent;
194→}
195→
196→.sd-messages::-webkit-scrollbar-thumb {
197→  background: #444;
198→  border-radius: 3px;
199→}
200→
201→.sd-messages::-webkit-scrollbar-thumb:hover {
202→  background: #555;
203→}
